#define MAX_TREASURES 10000
#define MAX_VERTICES 100

typedef struct {
    double x, y;
} Point;

int point_in_polygon(Point p, Point *poly, int n) {
    int count = 0;
    for (int i = 0; i < n; i++) {
        Point a = poly[i];
        Point b = poly[(i+1) % n];
        if ((a.y <= p.y && b.y > p.y) || (b.y <= p.y && a.y > p.y)) {
            double xint = a.x + (p.y - a.y) / (b.y - a.y) * (b.x - a.x);
            if (p.x < xint) count++;
        }
    }
    return count % 2;
}

