#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

typedef struct {
    int x, y;
} Point;

static int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

static int lower_bound_int(int *a, int n, int x) {
    int l = 0, r = n;
    while (l < r) {
        int m = (l + r) >> 1;
        if (a[m] < x) l = m + 1;
        else r = m;
    }
    return l;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    Point *p = (Point *)malloc(sizeof(Point) * N);
    int *ys = (int *)malloc(sizeof(int) * N);

    for (int i = 0; i < N; i++) {
        scanf("%d %d", &p[i].x, &p[i].y);
        ys[i] = p[i].y;
    }

    qsort(ys, N, sizeof(int), cmp_int);

    int M = 0;
    for (int i = 0; i < N; i++) {
        if (i == 0 || ys[i] != ys[i - 1]) ys[M++] = ys[i];
    }

    ll **pref = (ll **)malloc(sizeof(ll *) * (N + 1));
    for (int i = 0; i <= N; i++) {
        pref[i] = (ll *)calloc(M + 1, sizeof(ll));
    }

    /* 
       Build 2D prefix sum on compressed coordinates.
       Since the original statement details are omitted, we assume:
       - There are N treasures at integer coordinates.
       - Then some number Q of rectangle queries follow.
       - Each query gives x1 y1 x2 y2 and asks count in inclusive rectangle.

       To support arbitrary x values without compression details from input,
       we sort points by x and build prefix over x-order.
    */

    Point *sorted = (Point *)malloc(sizeof(Point) * N);
    for (int i = 0; i < N; i++) sorted[i] = p[i];

    int cmp_point_x(const void *a, const void *b) {
        const Point *pa = (const Point *)a;
        const Point *pb = (const Point *)b;
        if (pa->x != pb->x) return (pa->x < pb->x) ? -1 : 1;
        if (pa->y != pb->y) return (pa->y < pb->y) ? -1 : 1;
        return 0;
    }

    qsort(sorted, N, sizeof(Point), cmp_point_x);

    int *xs = (int *)malloc(sizeof(int) * N);
    for (int i = 0; i < N; i++) xs[i] = sorted[i].x;

    for (int i = 1; i <= N; i++) {
        for (int j = 1; j <= M; j++) pref[i][j] = pref[i - 1][j];
        int yi = lower_bound_int(ys, M, sorted[i - 1].y) + 1;
        for (int j = yi; j <= M; j++) pref[i][j]++;
    }

    int Q;
    scanf("%d", &Q);
    while (Q--) {
        int x1, y1, x2, y2;
        scanf("%d %d %d %d", &x1, &y1, &x2, &y2);
        if (x1 > x2) { int t = x1; x1 = x2; x2 = t; }
        if (y1 > y2) { int t = y1; y1 = y2; y2 = t; }

        int rx = lower_bound_int(xs, N, x2 + 1);
        int lx = lower_bound_int(xs, N, x1);

        int ry = lower_bound_int(ys, M, y2 + 1);
        int ly = lower_bound_int(ys, M, y1);

        ll ans = pref[rx][ry] - pref[lx][ry] - pref[rx][ly] + pref[lx][ly];
        printf("%lld\n", ans);
    }

    for (int i = 0; i <= N; i++) free(pref[i]);
    free(pref);
    free(sorted);
    free(xs);
    free(ys);
    free(p);

    return 0;
}

