int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, Q;
    while (cin >> N >> Q) {
        vector<int> tx(N), ty(N);
        for (int i = 0; i < N; i++) {
            cin >> tx[i] >> ty[i];
        }

        vector<int> x1(Q), y1(Q), x2(Q), y2(Q);
        for (int i = 0; i < Q; i++) {
            cin >> x1[i] >> y1[i] >> x2[i] >> y2[i];
        }

        // Coordinate compression
        vector<int> xs, ys;
        for (int i = 0; i < N; i++) {
            xs.push_back(tx[i]);
            ys.push_back(ty[i]);
        }
        for (int i = 0; i < Q; i++) {
            xs.push_back(x1[i]);
            xs.push_back(x2[i]);
            ys.push_back(y1[i]);
            ys.push_back(y2[i]);
        }

        sort(xs.begin(), xs.end());
        xs.erase(unique(xs.begin(), xs.end()), xs.end());
        sort(ys.begin(), ys.end());
        ys.erase(unique(ys.begin(), ys.end()), ys.end());

        int W = xs.size();
        int H = ys.size();

        vector<vector<int>> grid(W + 1, vector<int>(H + 1, 0));

        for (int i = 0; i < N; i++) {
            int xi = lower_bound(xs.begin(), xs.end(), tx[i]) - xs.begin();
            int yi = lower_bound(ys.begin(), ys.end(), ty[i]) - ys.begin();
            grid[xi + 1][yi + 1]++;
        }

        // Build 2D prefix sum
        for (int i = 1; i <= W; i++)
            for (int j = 1; j <= H; j++)
                grid[i][j] += grid[i-1][j] + grid[i][j-1] - grid[i-1][j-1];

        for (int i = 0; i < Q; i++) {
            int lx = lower_bound(xs.begin(), xs.end(), x1[i]) - xs.begin();
            int rx = upper_bound(xs.begin(), xs.end(), x2[i]) - xs.begin();
            int ly = lower_bound(ys.begin(), ys.end(), y1[i]) - ys.begin();
            int ry = upper_bound(ys.begin(), ys.end(), y2[i]) - ys.begin();

            // Count treasures with x in [x1[i], x2[i]] and y in [y1[i], y2[i]]
            // Compressed indices: lx to rx-1, ly to ry-1
            if (lx >= rx || ly >= ry) {
                cout << 0 << "\n";
            } else {
                int ans = grid[rx][ry] - grid[lx][ry] - grid[rx][ly] + grid[lx][ly];
                cout << ans << "\n";
            }
        }
    }

    return 0;
}

