import java.io.*;
import java.util.*;

public class Main {
    // Fast scanner
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Event {
        long x;
        int type; // 0 = add point, 1 = query
        int y1, y2;
        int idx;
        int coef;

        Event(long x, int type, int y1, int y2, int idx, int coef) {
            this.x = x;
            this.type = type;
            this.y1 = y1;
            this.y2 = y2;
            this.idx = idx;
            this.coef = coef;
        }
    }

    static class BIT {
        int n;
        long[] bit;

        BIT(int n) {
            this.n = n;
            bit = new long[n + 2];
        }

        void add(int idx, long val) {
            for (int i = idx; i <= n; i += i & -i) bit[i] += val;
        }

        long sum(int idx) {
            long res = 0;
            for (int i = idx; i > 0; i -= i & -i) res += bit[i];
            return res;
        }

        long rangeSum(int l, int r) {
            if (l > r) return 0;
            return sum(r) - sum(l - 1);
        }
    }

    static int lowerBound(long[] a, int size, long key) {
        int l = 0, r = size;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] < key) l = m + 1;
            else r = m;
        }
        return l;
    }

    static int upperBound(long[] a, int size, long key) {
        int l = 0, r = size;
        while (l < r) {
            int m = (l + r) >>> 1;
            if (a[m] <= key) l = m + 1;
            else r = m;
        }
        return l;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int q = fs.nextInt();

        long[] px = new long[n];
        long[] py = new long[n];
        long[] ys = new long[n];

        for (int i = 0; i < n; i++) {
            px[i] = fs.nextLong();
            py[i] = fs.nextLong();
            ys[i] = py[i];
        }

        Arrays.sort(ys);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || ys[i] != ys[i - 1]) ys[m++] = ys[i];
        }

        Event[] events = new Event[n + 2 * q];
        int e = 0;

        for (int i = 0; i < n; i++) {
            int yIdx = lowerBound(ys, m, py[i]) + 1;
            events[e++] = new Event(px[i], 0, yIdx, yIdx, -1, 0);
        }

        long[] ans = new long[q];

        for (int i = 0; i < q; i++) {
            long x1 = fs.nextLong();
            long y1 = fs.nextLong();
            long x2 = fs.nextLong();
            long y2 = fs.nextLong();

            if (x1 > x2) {
                long t = x1; x1 = x2; x2 = t;
            }
            if (y1 > y2) {
                long t = y1; y1 = y2; y2 = t;
            }

            int l = lowerBound(ys, m, y1) + 1;
            int r = upperBound(ys, m, y2);

            if (l <= r) {
                events[e++] = new Event(x2, 1, l, r, i, +1);
                events[e++] = new Event(x1 - 1, 1, l, r, i, -1);
            }
        }

        Arrays.sort(events, 0, e, (a, b) -> {
            if (a.x != b.x) return Long.compare(a.x, b.x);
            return Integer.compare(a.type, b.type); // add points before queries at same x
        });

        BIT bit = new BIT(m);

        for (int i = 0; i < e; i++) {
            Event ev = events[i];
            if (ev.type == 0) {
                bit.add(ev.y1, 1);
            } else {
                ans[ev.idx] += ev.coef * bit.rangeSum(ev.y1, ev.y2);
            }
        }

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            sb.append(ans[i]).append('\n');
        }
        System.out.print(sb.toString());
    }
}
